import type {
  ConfidenceLevel,
  CredibilityFactorKey,
  RiskLevel,
  ShariahClassification,
  VerificationStatus,
} from "@/types/domain";

export interface SeedCredibilityInput {
  factorKey: CredibilityFactorKey;
  score: number | null;
  evidenceEn: string;
  evidenceAr: string;
  sourceName: string;
  sourceUrl: string | null;
  confidenceLevel: ConfidenceLevel;
  isAvailable: boolean;
}

export interface SeedScenarioInput {
  scenarioType: "BEARISH" | "BASE" | "BULLISH";
  assumptionsEn: string;
  assumptionsAr: string;
  catalystsEn: string;
  catalystsAr: string;
  risksEn: string;
  risksAr: string;
  timeHorizon: string;
  supportingEvidenceEn: string;
  supportingEvidenceAr: string;
  sourceUrl: string | null;
}

export interface SeedAssetProfile {
  symbol: string;
  baseAsset: string;
  name: string;
  category: string;
  officialWebsite: string;
  githubRepo: string | null;
  coingeckoId: string;
  descriptionEn: string;
  descriptionAr: string;
  shariah: {
    classification: ShariahClassification;
    authorityName: string;
    sourceUrl: string;
    assessmentDate: string;
    methodology: string;
    coreActivityNotesEn: string;
    coreActivityNotesAr: string;
    conditionsEn: string | null;
    conditionsAr: string | null;
    scholarlyDisagreementsEn: string;
    scholarlyDisagreementsAr: string;
    verificationStatus: VerificationStatus;
    confidenceLevel: ConfidenceLevel;
  };
  tokenomics: {
    inflationRatePct: number | null;
    insiderAllocationPct: number | null;
    teamAllocationPct: number | null;
    vcAllocationPct: number | null;
    communityAllocationPct: number | null;
    treasuryAllocationPct: number | null;
    unlockScheduleSummaryEn: string;
    unlockScheduleSummaryAr: string;
    nextMajorUnlockDate: string | null;
    nextMajorUnlockPct: number | null;
    tokenUtilityEn: string;
    tokenUtilityAr: string;
    burnMechanismEn: string;
    burnMechanismAr: string;
    stakingMechanismEn: string;
    stakingMechanismAr: string;
    governanceRightsEn: string;
    governanceRightsAr: string;
    riskFlags: string[];
    tokenomicsRisk: RiskLevel;
    sourceName: string;
    sourceUrl: string;
  };
  credibility: SeedCredibilityInput[];
  scenarios: SeedScenarioInput[];
}

const GENERAL_CRYPTO_FIQH_NOTE_EN =
  "No cryptocurrency holds unanimous global scholarly consensus. The International Islamic Fiqh Academy (IIFA) has called for further study, and several national fatwa bodies still prohibit or restrict crypto trading. Classifications reflect named contemporary Shariah screening organizations for Spot ownership only.";

const GENERAL_CRYPTO_FIQH_NOTE_AR =
  "لا توجد عملة مشفرة تحظى بإجماع فقهي عالمي؛ إذ أوصى مجمع الفقه الإسلامي الدولي بمزيد من الدراسة، وتتحفظ بعض دور الإفتاء الوطنية على العملات الرقمية. التصنيف يعكس منهجية جهة فحص شرعي معاصرة محددة للتداول الفوري (Spot) فقط.";

function buildStandardCredibility(params: {
  team: [number | null, string, string, string, string | null, ConfidenceLevel];
  tech: [number | null, string, string, string, string | null, ConfidenceLevel];
  audit: [number | null, string, string, string, string | null, ConfidenceLevel];
  adoption: [number | null, string, string, string, string | null, ConfidenceLevel];
  transparency: [number | null, string, string, string, string | null, ConfidenceLevel];
  dev: [number | null, string, string, string, string | null, ConfidenceLevel];
  partners: [number | null, string, string, string, string | null, ConfidenceLevel];
}): SeedCredibilityInput[] {
  const mapEntry = (
    factorKey: CredibilityFactorKey,
    t: [number | null, string, string, string, string | null, ConfidenceLevel]
  ): SeedCredibilityInput => ({
    factorKey,
    score: t[0],
    evidenceEn: t[1],
    evidenceAr: t[2],
    sourceName: t[3],
    sourceUrl: t[4],
    confidenceLevel: t[5],
    isAvailable: t[0] !== null,
  });

  return [
    mapEntry("team_credibility", params.team),
    mapEntry("technology_security", params.tech),
    mapEntry("independent_audits", params.audit),
    mapEntry("real_world_adoption", params.adoption),
    mapEntry("transparency_documentation", params.transparency),
    mapEntry("development_activity", params.dev),
    mapEntry("strategic_partnerships", params.partners),
  ];
}

function buildScenarios(params: {
  assetName: string;
  sourceUrl: string;
  bearEn: string;
  bearAr: string;
  bearRiskEn: string;
  bearRiskAr: string;
  baseEn: string;
  baseAr: string;
  baseCatEn: string;
  baseCatAr: string;
  bullEn: string;
  bullAr: string;
  bullCatEn: string;
  bullCatAr: string;
}): SeedScenarioInput[] {
  return [
    {
      scenarioType: "BEARISH",
      assumptionsEn: params.bearEn,
      assumptionsAr: params.bearAr,
      catalystsEn: "Macro liquidity tightening, competing ecosystems capturing market share, or regulatory friction.",
      catalystsAr: "تشديد السيولة العالمية، استحواذ منافسين على الحصة السوقية، أو قيود تنظيمية.",
      risksEn: params.bearRiskEn,
      risksAr: params.bearRiskAr,
      timeHorizon: "12–24 Months",
      supportingEvidenceEn: `Analytical stress scenario for ${params.assetName}; not a statistical probability or guaranteed forecast.`,
      supportingEvidenceAr: `سيناريو تحليلي متحفظ لعملة ${params.assetName}؛ ليس احتمالاً إحصائياً مضموناً ولا توقعاً سعرياً.`,
      sourceUrl: params.sourceUrl,
    },
    {
      scenarioType: "BASE",
      assumptionsEn: params.baseEn,
      assumptionsAr: params.baseAr,
      catalystsEn: params.baseCatEn,
      catalystsAr: params.baseCatAr,
      risksEn: "Cyclical crypto drawdowns, execution delays, and token supply overhang.",
      risksAr: "التقلبات الدورية لسوق العملات الرقمية، تأخر خارطة الطريق، وضغط المعروض.",
      timeHorizon: "12–36 Months",
      supportingEvidenceEn: `Baseline fundamental trajectory grounded in current public adoption and network disclosures for ${params.assetName}.`,
      supportingEvidenceAr: `المسار الأساسي المبني على بيانات التبني العامة الحالية وإفصاحات الشبكة لمشروع ${params.assetName}.`,
      sourceUrl: params.sourceUrl,
    },
    {
      scenarioType: "BULLISH",
      assumptionsEn: params.bullEn,
      assumptionsAr: params.bullAr,
      catalystsEn: params.bullCatEn,
      catalystsAr: params.bullCatAr,
      risksEn: "Valuation overheating, unsustainable speculation, and unexpected smart-contract or governance shocks.",
      risksAr: "تضخم التقييم السعري، المضاربة المفرطة، أو صدمات تقنية/حوكمة غير متوقعة.",
      timeHorizon: "24–48 Months",
      supportingEvidenceEn: `Constructive expansion thesis conditional on measurable network usage growth for ${params.assetName}.`,
      supportingEvidenceAr: `فرضية توسع إيجابية مشروطة بنمو فعلي قابل للقياس في استخدام شبكة ${params.assetName}.`,
      sourceUrl: params.sourceUrl,
    },
  ];
}

